fn listed_with_catalog(row: &ListingRow) -> FunctionDefinition {
    let (name, signature, receiver, parameters, returns, deterministic, host_backed, origin, description) = *row;
    FunctionDefinition {
        name: name.into(),
        signature: signature.into(),
        receiver_type: receiver.map(Into::into),
        parameters: parameters.iter().map(|parameter| parameter.to_string()).collect(),
        returns: returns.into(),
        deterministic,
        host_backed,
        throws: None,
        description: description.map(Into::into),
        origin: origin.map(Into::into),
    }
}

#[test]
fn lists_the_library_and_the_catalog_together_as_node_does() {
    let with_catalog = |enable_optional_types: bool| {
        let mut environment = CelEnvironment::new(CelEnvironmentOptions { enable_optional_types, ..Default::default() });
        register_function_catalog(&mut environment, RegisterCatalogOptions::default());
        environment.definitions().functions
    };
    let expected: Vec<FunctionDefinition> = NODE_CATALOG_LISTING.iter().map(listed_with_catalog).collect();
    assert_eq!(with_catalog(true), expected);
    assert_eq!(expected.len(), 300);
    let optional_only: Vec<&str> = NODE_FUNCTIONS.iter().filter(|row| row.0).map(|row| row.2).collect();
    let without: Vec<FunctionDefinition> =
        expected.into_iter().filter(|row| !optional_only.contains(&row.signature.as_str())).collect();
    assert_eq!(with_catalog(false), without);
    assert_eq!(without.len(), 293);
}
